INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 12, 'theory', 'Quiz: hash tables, trees, and heaps');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 0, 'Why can''t you simply clear the slot of a deleted element in open addressing?', '["Because memory cannot be freed", "Because keys must be unique", "It would slow down the hash function", "The probe chain breaks and elements behind it become \"not found\"; you need a tombstone or a backward shift"]', 3, 'A search stops at an empty slot. If you clear a slot in the middle of a chain, keys that lay further along can no longer be found. You either mark a tombstone or shift the rest of the chain back.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 1, 'What happens to pointers to table elements after the table grows (is rebuilt)?', '["They become invalid: the elements are moved to a new array", "They stay valid", "They are updated automatically", "They point to old copies that are safe to read"]', 0, 'On growth a new array is created and the elements are inserted again; the old one is freed. A pointer into the table must not be used after that.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 2, 'What is the balance condition of an AVL tree?', '["All leaves are at the same depth", "For every node, the difference of subtree heights is at most 1 in absolute value", "The left subtree is no smaller than the right", "The height of the tree equals the number of nodes"]', 1, 'This condition guarantees a height on the order of log n. After an insertion or a deletion it is restored with rotations.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 3, 'What are the indices of the children and the parent of element i in a binary heap stored in an array (zero-based)?', '["Children 2i and 2i + 1, parent i / 2", "Children i + 1 and i + 2, parent i − 1", "Children 2i + 1 and 2i + 2, parent (i − 1) / 2", "Children 2i − 1 and 2i, parent i / 2 − 1"]', 2, 'The formulas 2i + 1, 2i + 2 and (i − 1) / 2 match the root in a[0]. For one-based numbering they are different: 2i, 2i + 1 and i / 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 12, 4, 'How do you reliably check that your data structure is correct in tests?', '["Call an invariant function after every operation and compare the results with a simple model on the same random operations", "Print the contents and look at them", "One test on an empty structure is enough", "No need if it compiled without warnings"]', 0, 'An invariant catches a violation immediately, and comparison with a model (for example, on an array) catches any discrepancy in results. Everything runs under sanitizers.');
